    "lmpcWorkflowStep2Desc": "आयातकों के लिए: राष्ट्रीय एकल खिड़की प्रणाली (NSWS) या lm.doca.gov.in पर। निर्माताओं के लिए: संबंधित राज्य विधिक मापविज्ञान पोर्टल पर।",
    "lmpcWorkflowStep3Title": "दस्तावेज़ अपलोड और शुल्क भुगतान",
    "lmpcWorkflowStep3Desc": "जीएसटी, निगमन प्रमाणपत्र, निदेशक केवाईसी और लेबल डिजाइन जमा करें। भारतकोश या राज्य ट्रेजरी द्वारा वैधानिक शुल्क का भुगतान करें।",
    "lmpcWorkflowStep4Title": "समीक्षा और प्रमाणपत्र जारी करना",
    "lmpcWorkflowStep4Desc": "विधिक मापविज्ञान नियंत्रक/निदेशक आवेदन की समीक्षा करते हैं। अनुपालित होने पर डिजिटल रूप से आधिकारिक LMPC प्रमाणपत्र जारी किया जाता है।",
    "lmpcFaqHeading": "नियम 27 पर अक्सर पूछे जाने वाले वैधानिक प्रश्न",
    "lmpcFaq1Q": "एलएमपीसी प्रमाणपत्र की वैधता अवधि क्या है?",
    "lmpcFaq1A": "केंद्रीय नियमों के तहत, आयातकों के लिए एलएमपीसी पंजीकरण आजीवन मान्य रहता है जब तक कि कंपनी का पता या नाम न बदले। राज्य पैकर पंजीकरण के लिए आवधिक नवीनीकरण आवश्यक हो सकता है।",
    "lmpcFaq2Q": "क्या सीमा शुल्क निकासी के लिए एलएमपीसी प्रमाणपत्र आवश्यक है?",
    "lmpcFaq2A": "हाँ। बंदरगाहों या एयर कार्गो पर भारतीय सीमा शुल्क अधिकारी आयातित पैकेज्ड वस्तुओं के लिए एलएमपीसी पंजीकरण की अनिवार्य जांच करते हैं।",
    "lmpcFaq3Q": "क्या छोटे पैकेजों को नियमों से छूट प्राप्त है?",
    "lmpcFaq3A": "10 ग्राम या 10 मिलीलीटर से कम वजन/मात्रा वाले पैकेजों को कुछ घोषणा नियमों से छूट है, लेकिन 50 किलोग्राम से अधिक के कृषि पैकेज अलग अनुसूचियों के अंतर्गत आते हैं।",
