    "lmpcMandateHeading": "সংবিধিবদ্ধ আদেশ: নিয়ম ২৭ নিবন্ধন",
    "lmpcMandateText": "প্যাকেজড পণ্য বিধি ২০১১ এর নিয়ম ২৭ অনুযায়ী, ভারতে পণ্য প্যাকিং বা আমদানিকারক প্রত্যেক ব্যক্তি বা সংস্থাকে ৯০ দিনের মধ্যে নিবন্ধন করতে হবে।",
