    "lmpcWorkflowHeading": "ধাপে ধাপে নিবন্ধন প্রক্রিয়া",
    "lmpcWorkflowStep1Title": "লেবেল প্রাক-সম্মতি অডিট",
    "lmpcWorkflowStep1Desc": "প্যাক-পরীক্ষক এআই দিয়ে ৮টি বাধ্যতামূলক ঘোষণা পরীক্ষা করুন। ফন্টের উচ্চতা যাচাই করুন।",
    "lmpcWorkflowStep2Title": "অনলাইন আবেদন দাখিল",
    "lmpcWorkflowStep2Desc": "আমদানিকারকদের জন্য: NSWS বা lm.doca.gov.in-এ। প্রস্তুতকারকদের জন্য: রাজ্য আইনি পরিমাপবিজ্ঞান পোর্টালে।",
    "lmpcWorkflowStep3Title": "নথিপত্র আপলোড ও ফি প্রদান",
    "lmpcWorkflowStep3Desc": "জিএসটি, ইনকর্পোরেশন ও লেবেল ডিজাইন জমা দিন। ভারতকোষ বা রাজ্য ট্রেজারির মাধ্যমে ফি প্রদান করুন।",
    "lmpcWorkflowStep4Title": "যাচাই ও সার্টিফিকেট প্রদান",
    "lmpcWorkflowStep4Desc": "নিয়ামক আবেদনটি যাচাই করেন এবং সম্মতি নিশ্চিত হলে ডিজিটাল এলএমপিসি সার্টিফিকেট প্রদান করেন।",
    "lmpcFaqHeading": "নিয়ম ২৭ সম্পর্কিত সাধারণ প্রশ্নোত্তর",
    "lmpcFaq1Q": "এলএমপিসি সার্টিফিকেটের মেয়াদ কতদিন?",
    "lmpcFaq1A": "কেন্দ্রীয় নিয়মে, আমদানিকারক নিবন্ধনের মেয়াদ আজীবন থাকে যদি না ব্যবসার নাম বা ঠিকানা পরিবর্তিত হয়।",
    "lmpcFaq2Q": "কাস্টমস ক্লিয়ারেন্সের জন্য কি এলএমপিসি প্রয়োজন?",
    "lmpcFaq2A": "হ্যাঁ। ভারতীয় শুল্ক কর্তৃপক্ষ আমদানিকৃত প্যাকেজ পণ্যের জন্য এলএমপিসি বাধ্যতামূলকভাবে পরীক্ষা করে।",
    "lmpcFaq3Q": "ছোট প্যাকেজ কি নিয়ম থেকে অব্যাহতি পায়?",
    "lmpcFaq3A": "১০ গ্রাম বা ১০ মিলিলিটারের কম প্যাকেজ কিছু ঘোষণা থেকে অব্যাহতি পায়, কিন্তু ৫০ কেজির বেশি পণ্যের জন্য আলাদা নিয়ম প্রযোজ্য।",
