    "lmpcMainDesc": "உற்பத்தியாளர்கள் மற்றும் இறக்குமதியாளர்கள் விதி 27 இன் கீழ் LMPC பதிவு பெறுவதற்கான முழுமையான அதிகாரப்பூர்வ வழிகாட்டி.",
