    "lmpcDocChecklistHeading": "ஆவண தயார்நிலை சரிபார்ப்புப் பட்டியல்",
    "lmpcDoc1": "நிறுவன பதிவு சான்றிதழ் / கூட்டாண்மை பத்திரம் / MSME",
    "lmpcDoc2": "செல்லுபடியாகும் ஜிஎஸ்டி பதிவு சான்றிதழ்",
    "lmpcDoc3": "தொழிற்சாலை உரிமம் / FSSAI உரிமம் / வர்த்தக உரிமம்",
    "lmpcDoc4": "மாதிரி லேபிள் வடிவமைப்பு (விதி 6 இன் படி)",
    "lmpcDoc5": "பேக் செய்யப்படும் அனைத்து பொருட்களின் பட்டியல்",
    "lmpcDoc6": "அங்கீகரிக்கப்பட்ட கையொப்பமிட்டவர் KYC (பான் & ஆதார்)",
    "lmpcPreAuditLink": "பேக்-பரீக்ஷக் AI உடன் லேபிளை முன்கூட்டியே தணிக்கை செய்க",
    "lmpcMandateHeading": "சட்டப்பூர்வ ஆணை: விதி 27 பதிவு",
    "lmpcMandateText": "விதி 27 இன் படி, இந்தியாவில் பொருட்களை பேக் செய்யும் அல்லது இறக்குமதி செய்யும் அனைவரும் 90 நாட்களுக்குள் பதிவு செய்ய வேண்டும்.",
    "lmpcMandateWarning": "சட்டப்பூர்வ எச்சரிக்கை: செல்லுபடியாகும் பதிவு இல்லாமல் விற்பனை செய்வது பிரிவு 36 இன் கீழ் தண்டனைக்குரிய குற்றமாகும்.",
    "lmpcWorkflowHeading": "படிப்படியான பதிவு செயல்முறை",
    "lmpcWorkflowStep1Title": "லேபிள் முன்-இணக்க தணிக்கை",
    "lmpcWorkflowStep1Desc": "பேக்-பரீக்ஷக் AI மூலம் 8 கட்டாய அறிவிப்புகளை சரிபார்க்கவும். எழுத்துரு உயரத்தை உறுதிப்படுத்தவும்.",
    "lmpcWorkflowStep2Title": "ஆன்லைன் விண்ணப்பம் சமர்ப்பித்தல்",
    "lmpcWorkflowStep2Desc": "இறக்குமதியாளர்களுக்கு: NSWS அல்லது lm.doca.gov.in மூலம். உற்பத்தியாளர்களுக்கு: மாநில போர்ட்டல் மூலம்.",
    "lmpcWorkflowStep3Title": "ஆவணங்கள் பதிவேற்றம் & கட்டணம் செலுத்துதல்",
    "lmpcWorkflowStep3Desc": "ஜிஎஸ்டி, நிறுவன சான்றிதழ் சமர்ப்பித்து பாரத்கோஷ் மூலம் சட்டப்பூர்வ கட்டணத்தை செலுத்தவும்.",
    "lmpcWorkflowStep4Title": "ஆய்வு மற்றும் சான்றிதழ் வழங்குதல்",
    "lmpcWorkflowStep4Desc": "விண்ணப்பம் பரிசீலிக்கப்பட்டு விதிமுறைகள் பூர்த்தியானதும் டிஜிட்டல் சான்றிதழ் வழங்கப்படும்.",
    "lmpcFaqHeading": "விதி 27 குறித்த பொதுவான கேள்விகள்",
    "lmpcFaq1Q": "LMPC சான்றிதழின் செல்லுபடியாகும் காலம் என்ன?",
    "lmpcFaq1A": "இறக்குமதியாளர்களுக்கு முகவரி மாறாத வரை வாழ்நாள் முழுவதும் செல்லுபடியாகும்.",
    "lmpcFaq2Q": "சுங்க அனுமதியில் LMPC அவசியமா?",
    "lmpcFaq2A": "ஆம். சுங்க அதிகாரிகள் இறக்குமதி செய்யப்பட்ட பொருட்களுக்கு LMPC ஐ கண்டிப்பாக சோதிக்கிறார்கள்.",
    "lmpcFaq3Q": "சிறிய பாக்கெட்டுகளுக்கு விலக்கு உண்டா?",
    "lmpcFaq3A": "10 கிராம் அல்லது 10 மில்லிக்கு குறைவான பாக்கெட்டுகளுக்கு சில அறிவிப்புகளிலிருந்து விலக்கு உண்டு.",
