    "lmpcMandateHeading": "చట్టబద్ధమైన నిబంధన: రూల్ 27 రిజిస్ట్రేషన్",
    "lmpcMandateText": "రూల్ 27 ప్రకారం, భారతదేశంలో వస్తువులను ప్యాక్ చేసే లేదా దిగుమతి చేసుకునే ప్రతి ఒక్కరూ 90 రోజుల్లోగా నమోదు చేసుకోవాలి.",
