    "lmpcWorkflowStep1Title": "ಲೇಬಲ್ ಪೂರ್ವ-ಅನುಸರಣೆ ಪರಿಶೋಧನೆ",
    "lmpcWorkflowStep1Desc": "ಪ್ಯಾಕ್-ಪರೀಕ್ಷಕ್ AI ನೊಂದಿಗೆ 8 ಕಡ್ಡಾಯ ಘೋಷಣೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ. ಫಾಂಟ್ ಎತ್ತರವನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
    "lmpcWorkflowStep2Title": "ಆನ್‌ಲೈನ್ ಅರ್ಜಿ ಸಲ್ಲಿಕೆ",
    "lmpcWorkflowStep2Desc": "ಆಮದುದಾರರಿಗೆ: NSWS ಅಥವಾ lm.doca.gov.in ಮೂಲಕ. ತಯಾರಕರಿಗೆ: ರಾಜ್ಯ ಲೀಗಲ್ ಮೆಟ್ರಾಲಜಿ ಪೋರ್ಟಲ್ ಮೂಲಕ.",
    "lmpcWorkflowStep3Title": "ದಾಖಲೆಗಳ ಅಪ್‌ಲೋಡ್ ಮತ್ತು ಶುಲ್ಕ ಪಾವತಿ",
    "lmpcWorkflowStep3Desc": "ಜಿಎಸ್‌ಟಿ, ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಿ ಮತ್ತು ಭಾರತಕೋಶದ ಮೂಲಕ ಶುಲ್ಕ ಪಾವತಿಸಿ.",
