    "lmpcWorkflowStep4Desc": "ಅರ್ಜಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ನಿಯಮಗಳು ಪಾಲನೆಯಾಗಿದ್ದರೆ ಡಿಜಿಟಲ್ LMPC ಪ್ರಮಾಣಪತ್ರ ನೀಡಲಾಗುತ್ತದೆ.",
    "lmpcFaqHeading": "ನಿಯಮ 27 ರ ಕುರಿತು ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು",
    "lmpcFaq1Q": "LMPC ಪ್ರಮಾಣಪತ್ರದ ಮಾನ್ಯತೆಯ ಅವಧಿ ಎಷ್ಟು?",
    "lmpcFaq1A": "ಆಮದುದಾರರಿಗೆ ವಿಳಾಸ ಅಥವಾ ಹೆಸರು ಬದಲಾಗದ ಹೊರತು ಜೀವಮಾನದ ಮಾನ್ಯತೆ ಇರುತ್ತದೆ.",
    "lmpcFaq2Q": "ಕಸ್ಟಮ್ಸ್ ಕ್ಲಿಯರೆನ್ಸ್‌ಗೆ LMPC ಅಗತ್ಯವಿದೆಯೇ?",
    "lmpcFaq2A": "ಹೌದು. ಕಸ್ಟಮ್ಸ್ ಅಧಿಕಾರಿಗಳು ಆಮದು ಮಾಡಿದ ಸರಕುಗಳಿಗೆ LMPC ಯನ್ನು ಕಡ್ಡಾಯವಾಗಿ ಪರಿಶೀಲಿಸುತ್ತಾರೆ.",
    "lmpcFaq3Q": "ಸಣ್ಣ ಪ್ಯಾಕೆಟ್‌ಗಳಿಗೆ ವಿನಾಯಿತಿ ಇದೆಯೇ?",
    "lmpcFaq3A": "10 ಗ್ರಾಂ ಅಥವಾ 10 ಮಿಲಿಗಿಂತ ಕಡಿಮೆ ತೂಕದ ಪ್ಯಾಕೆಟ್‌ಗಳಿಗೆ ಕೆಲವು ನಿಯಮಗಳಿಂದ ವಿನಾಯಿತಿ ಇದೆ.",
