    "lmpcMandateText": "റൂൾ 27 പ്രകാരം, ഇന്ത്യയിൽ സാധനങ്ങൾ പാക്ക് ചെയ്യുകയോ ഇറക്കുമതി ചെയ്യുകയോ ചെയ്യുന്നവർ 90 ദിവസത്തിനകം രജിസ്റ്റർ ചെയ്യണം.",
